using UnityEngine;

// Dados das 5 fases, ja em coordenadas do mundo (unidades da Unity, centro do mapa em 0,0).
// Cada fase tem um ou mais cenarios empilhados de cima para baixo (Parts), cada um com 27.52 x 15.36 unidades:
// fases 1 a 3 tem um cenario; a fase 4 junta mercado + shopping; a fase 5 junta mercado + shopping + parque.
// Paredes sao retangulos (x0, y0, x1, y1). Este arquivo e gerado pelo script gen4.py.
public class LevelDef
{
    public string Name, Title, Story, Outfit;
    public string[] Parts, PartNames;     // fundos (Resources/Art/Cenarios) de cima para baixo
    public float WorldW, WorldH;
    public float[,] Walls;
    public Vector2[] ChildSpawns, MomSpots, PlacePos;
    public string[] PlaceNames;
    public Color Tint;
    public float MomShirt, MomSkirt; // matiz em graus; -1 = cor original do desenho
    public const float PartH = 15.36f;
}

public static class Levels
{
    public const int Count = 5;

    public static LevelDef Get(int i)
    {
        i = Mathf.Clamp(i, 0, Count - 1);
        switch (i)
        {
            case 0: return L1();
            case 1: return L2();
            case 2: return L3();
            case 3: return L4();
            case 4: return L5();
        }
        return L1();
    }

